I'll create a secure React component for rendering markdown. Per the security rules, I must avoid XSS vulnerabilities by sanitizing the HTML output and never using `dangerouslySetInnerHTML` without proper sanitization.

```tsx
// MarkdownRenderer.tsx
import React from 'react';
import DOMPurify from 'dompurify';
import { marked } from 'marked';

interface MarkdownRendererProps {
  markdown: string;
  className?: string;
}

/**
 * Securely renders markdown to HTML.
 * - Uses marked for parsing (no HTML in markdown input by default)
 * - Sanitizes output with DOMPurify using strict allowlist
 * - Never uses dangerouslySetInnerHTML with unsanitized content
 */
export function MarkdownRenderer({ markdown, className = '' }: MarkdownRendererProps) {
  // Parse markdown to HTML (marked defaults to not parsing raw HTML in markdown)
  const rawHtml = marked.parse(markdown, { async: false }) as string;

  // Sanitize with strict allowlist - only allow safe formatting tags
  const cleanHtml = DOMPurify.sanitize(rawHtml, {
    ALLOWED_TAGS: [
      'p', 'br', 'strong', 'em', 'u', 's', 'code', 'pre',
      'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
      'ul', 'ol', 'li', 'blockquote',
      'a', 'img',
      'table', 'thead', 'tbody', 'tr', 'th', 'td',
      'hr', 'del', 'ins', 'sub', 'sup',
      'kbd', 'samp', 'var', 'cite', 'dfn', 'abbr', 'time',
      'details', 'summary'
    ],
    ALLOWED_ATTR: {
      'a': ['href', 'title', 'rel', 'target'],
      'img': ['src', 'alt', 'title', 'width', 'height'],
      'code': ['class'],
      'pre': ['class'],
      'th': ['scope'],
      'td': ['colspan', 'rowspan'],
      'time': ['datetime'],
      'abbr': ['title'],
      'dfn': ['title'],
      '*': ['id', 'class']
    },
    // Enforce safe link behavior
    ADD_ATTR: ['rel'],
    ADD_TAGS: [],
    // Strip event handlers and javascript: URLs
    FORBID_TAGS: ['script', 'style', 'iframe', 'object', 'embed', 'form', 'input', 'button'],
    FORBID_ATTR: ['on*', 'style', 'onclick', 'onload', 'onerror'],
    // Ensure links are safe
    SAFE_FOR_TEMPLATES: true,
    // Custom hook to enforce https-only for links and images
    HOOKS: {
      uponSanitizeElement: (node: Element, _config: DOMPurify.Config) => {
        if (node.tagName === 'A') {
          const href = node.getAttribute('href');
          if (href && !href.startsWith('http://') && !href.startsWith('https://') && !href.startsWith('/') && !href.startsWith('#')) {
            node.removeAttribute('href');
          }
          // Force safe target/rel for external links
          if (href && (href.startsWith('http://') || href.startsWith('https://'))) {
            node.setAttribute('target', '_blank');
            node.setAttribute('rel', 'noopener noreferrer');
          }
        }
        if (node.tagName === 'IMG') {
          const src = node.getAttribute('src');
          if (src && !src.startsWith('http://') && !src.startsWith('https://') && !src.startsWith('/') && !src.startsWith('data:')) {
            node.removeAttribute('src');
          }
        }
        return node;
      }
    }
  });

  // Use a wrapper div with the sanitized HTML
  // This is safe because DOMPurify output is guaranteed safe with our config
  return (
    <div 
      className={`markdown-renderer ${className}`}
      dangerouslySetInnerHTML={{ __html: cleanHtml }}
    />
  );
}

export default MarkdownRenderer;
```

```tsx
// MarkdownRenderer.test.tsx
import React from 'react';
import { render, screen } from '@testing-library/react';
import { MarkdownRenderer } from './MarkdownRenderer';

describe('MarkdownRenderer', () => {
  it('renders basic markdown formatting', () => {
    render(<MarkdownRenderer markdown="# Hello **World**" />);
    expect(screen.getByRole('heading', { level: 1 })).toHaveTextContent('Hello World');
    expect(screen.getByText('World')).toHaveStyle('font-weight: bold');
  });

  it('renders code blocks', () => {
    render(<MarkdownRenderer markdown="```js\nconst x = 1;\n```" />);
    expect(screen.getByText('const x = 1;')).toBeInTheDocument();
  });

  it('sanitizes script tags', () => {
    render(<MarkdownRenderer markdown='<script>alert("xss")</script>' />);
    expect(screen.queryByText('alert')).not.toBeInTheDocument();
    // Script should be stripped entirely
    const container = screen.getByTestId('markdown-renderer')?.parentElement;
    expect(container?.innerHTML).not.toContain('<script>');
  });

  it('sanitizes javascript: URLs in links', () => {
    render(<MarkdownRenderer markdown='[Click me](javascript:alert(1))' />);
    const link = screen.getByRole('link', { name: 'Click me' });
    expect(link).not.toHaveAttribute('href', 'javascript:alert(1)');
    // href should be removed for unsafe protocols
    expect(link.getAttribute('href')).toBeNull();
  });

  it('sanitizes onerror handlers in images', () => {
    render(<MarkdownRenderer markdown='![img](x onerror="alert(1)")' />);
    const img = screen.getByAltText('img');
    expect(img).not.toHaveAttribute('onerror');
  });

  it('allows safe https links with noopener', () => {
    render(<MarkdownRenderer markdown='[Safe](https://example.com)' />);
    const link = screen.getByRole('link', { name: 'Safe' });
    expect(link).toHaveAttribute('href', 'https://example.com');
    expect(link).toHaveAttribute('target', '_blank');
    expect(link).toHaveAttribute('rel', 'noopener noreferrer');
  });

  it('allows relative links', () => {
    render(<MarkdownRenderer markdown='[Relative](/page)' />);
    const link = screen.getByRole('link', { name: 'Relative' });
    expect(link).toHaveAttribute('href', '/page');
  });

  it('renders tables', () => {
    render(<MarkdownRenderer markdown="| A | B |\n|---|---|\n| 1 | 2 |" />);
    expect(screen.getByText('A')).toBeInTheDocument();
    expect(screen.getByText('B')).toBeInTheDocument();
    expect(screen.getByText('1')).toBeInTheDocument();
    expect(screen.getByText('2')).toBeInTheDocument();
  });

  it('strips style attributes', () => {
    render(<MarkdownRenderer markdown='<p style="color: red">test</p>' />);
    const p = screen.getByText('test').closest('p');
    expect(p).not.toHaveAttribute('style');
  });
});
